/**
 * Normalized lookup map for fast O(1) technology resolution by ID, name, or alias.
 */
function normalizeString(val: string): string {
  return String(val || "")
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]/g, "");
}

const NORM_LOOKUP = new Map<string, Technology>();

for (const tech of Object.values(CONFIRMED_TECHNOLOGIES)) {
  NORM_LOOKUP.set(normalizeString(tech.id), tech);
  NORM_LOOKUP.set(normalizeString(tech.name), tech);
  NORM_LOOKUP.set(normalizeString(tech.title), tech);
  for (const alias of tech.aliases) {
    NORM_LOOKUP.set(normalizeString(alias), tech);
  }
}

/**
 * Resolves a technology by ID, full name, or common alias.
 * Returns undefined if the technology is unknown.
 */
export function getTechnology(nameOrAlias: string): Technology | undefined {
  if (!nameOrAlias) return undefined;
  const key = normalizeString(nameOrAlias);
  return NORM_LOOKUP.get(key);
}

/**
 * Returns all confirmed technologies configured for the main Stack cards section.
 */
export function getStackTechnologies(): Technology[] {
  return Object.values(CONFIRMED_TECHNOLOGIES).filter((t) => t.inStack !== false);
}
